import java.util.*;

class Solution {
    Map<String, Integer> res = new TreeMap<>();
    Stack<Integer> stack = new Stack<>();
    int multiplier = 1;

    public String countOfAtoms(String formula) {
        int i = formula.length() - 1;
        stack.push(1);

        while (i >= 0) {
            if (formula.charAt(i) == ')') {
                i--;
                int end = i;
                while (i >= 0 && Character.isDigit(formula.charAt(i))) i--;
                int val = (end == i) ? 1 : Integer.parseint(formula.substring(i + 1, end + 1));
                int currentTop = stack.pop();
                stack.push(currentTop * val);
            } else if (formula.charAt(i) == '(') {
                i--;
                // The multiplier for this parenthesis was already applied to the stack top
            } else {
                int end = i;
                while (i >= 0 && Character.isLowerCase(formula.charAt(i))) i--;
                String name = formula.substring(i, end + 1);
                i--;
                int digitEnd = i + 1;
                while (i >= 0 && Character.isDigit(formula.charAt(i))) i--;
                int val = (digitEnd == i + 1) ? 1 : Integer.parseint(formula.substring(i + 1, digitEnd));

                int currentMultiplier = stack.peek();
                res.put(name, res.getOrDefault(name, 0) + val * currentMultiplier);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> entry : res.entrySet()) {
            sb.append(entry.getKey());
            if (entry.getValue() > 1) sb.append(entry.getValue());
        }
        return sb.toString();
    }
}
