            pos += 1
            right, pos = parse_factor(tokens, pos)
            if op == '*':
                left = left * right
            else:
                left = left / right
        return left, pos

    def parse_factor(tokens, pos=0):
        token = tokens[pos]
        if token == '(':
            pos += 1
            result, pos = parse_expression(tokens, pos)
            if pos < len(tokens) and tokens[pos] == ')':
