from typing import Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def flipEquiv(root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
    if not root1 and not root2:
        return True
    if not root1 or not root2:
        return False
    if root1.val != root2.val:
        return False

    # Check without flip
    no_flip = flipEquiv(root1.left, root2.left) and flipEquiv(root1.right, root2.right)

    # Check with flip
    flip = flipEquiv(root1.left, root2.right) and flipEquiv(root1.right, root2.left)

    return no_flip or flip
